// GERADO A PARTIR DO GEOJSON OFICIAL DAS RAs DO DF.
// Não requer d3-geo, Leaflet, MapLibre ou fetch externo.
// O filtro deve usar o código da RA (ex.: "RA-V") como chave estável.

export type RAData = {
  id: string;
  code: string;
  number: number;
  sourceName: string;
  displayName: string;
  areaKm2: number;
  geometryType: "Polygon" | "MultiPolygon";
  path: string;
  bounds: { x: number; y: number; width: number; height: number };
  viewBox: string;
  labelPoint: { x: number; y: number };
};

export const MAP_WIDTH = 1200;
export const MAP_HEIGHT = 717.6;
export const MAP_VIEWBOX = "0 0 1200 717.6";

export const GEO_BOUNDS = {
  minLon: -48.285892396648,
  maxLon: -47.310135530380,
  minLat: -16.050360523604,
  maxLat: -15.501819582901,
  cosLat: 0.962331534276,
  scale: 1235.354654653284,
  padding: 20.0,
} as const;

// Use esta função para colocar pontos reais de ocorrência (longitude/latitude)
// exatamente no mesmo sistema de coordenadas dos polígonos.
export function projectLonLat(longitude: number, latitude: number) {
  const x =
    GEO_BOUNDS.padding +
    (longitude - GEO_BOUNDS.minLon) * GEO_BOUNDS.cosLat * GEO_BOUNDS.scale;
  const y =
    GEO_BOUNDS.padding +
    (GEO_BOUNDS.maxLat - latitude) * GEO_BOUNDS.scale;
  return { x, y };
}

